import{_ as e,o as t,c as s,Q as i}from"./chunks/framework.b67c47e6.js";const o="/assets/issues-view.3edb20be.svg",f=JSON.parse('{"title":"Issues Management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/issues/index.md","filePath":"guide/issues/index.md","lastUpdated":1790346505000}'),a={name:"guide/issues/index.md"},r=i('<h1 id="issues-management" tabindex="-1">Issues Management <a class="header-anchor" href="#issues-management" aria-label="Permalink to &quot;Issues Management&quot;">​</a></h1><p>The Issues view provides a centralized overview of all production issues and quality control records across a project. Open it from the project menu: <strong>Production → Production Issues</strong>.</p><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#issue-categories">Issue Categories</a></li><li><a href="#issue-fields">Issue Fields</a></li><li><a href="#creating-issues">Creating Issues</a></li><li><a href="#editing-and-deleting">Editing and Deleting</a></li><li><a href="#resolving-issues">Resolving Issues</a></li><li><a href="#sorting">Sorting</a></li></ul></nav><p><img src="'+o+'" alt="Production Issues, with the detail of one issue open"></p><ol><li>The summary: all issues, and how many of each category.</li><li>The table. A tick in <strong>Status</strong> means the issue is solved.</li><li><strong>Edit issue</strong>, <strong>Solve issue</strong> and <strong>Delete</strong>, in the detail panel.</li></ol><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>At the top, a summary card shows:</p><ul><li>Total issue count</li><li>Breakdown by category: <strong>Quality Control Issue</strong> and <strong>Production Issue</strong></li></ul><p>Below the summary, a data table lists all issues of the project.</p><h2 id="issue-categories" tabindex="-1">Issue Categories <a class="header-anchor" href="#issue-categories" aria-label="Permalink to &quot;Issue Categories&quot;">​</a></h2><table><thead><tr><th>Category</th><th>Description</th></tr></thead><tbody><tr><td><strong>Quality Control Issue</strong></td><td>Issues related to product quality, compliance, or inspection findings. They appear in the <a href="/guide/reports/quality_control/">Quality Control Report</a>.</td></tr><tr><td><strong>Production Issue</strong></td><td>Problems encountered during the manufacturing process (delays, equipment, material defects). They appear in the <a href="/guide/reports/issues/">Issues Report</a>.</td></tr></tbody></table><h2 id="issue-fields" tabindex="-1">Issue Fields <a class="header-anchor" href="#issue-fields" aria-label="Permalink to &quot;Issue Fields&quot;">​</a></h2><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Short description of the issue. Click it to open the issue detail.</td></tr><tr><td><strong>Text</strong></td><td>Detailed explanation of the problem.</td></tr><tr><td><strong>Category</strong></td><td>Quality control or production issue.</td></tr><tr><td><strong>Constructible</strong></td><td>The assembly or module affected, with its position in the batch.</td></tr><tr><td><strong>User</strong></td><td>The user who reported the issue.</td></tr><tr><td><strong>Created</strong></td><td>When the issue was reported.</td></tr><tr><td><strong>Status</strong></td><td>Open or solved. The table shows a check when the issue is solved.</td></tr><tr><td><strong>Pictures</strong></td><td>Optional photos or files attached to the issue.</td></tr></tbody></table><p>The issue detail also shows the design and its revision, and the engineering contact of the project when one is set.</p><h2 id="creating-issues" tabindex="-1">Creating Issues <a class="header-anchor" href="#creating-issues" aria-label="Permalink to &quot;Creating Issues&quot;">​</a></h2><p>Issues are created in the <a href="/guide/viewer/#issues">3D Viewer</a>: while viewing a constructible, click <strong>Note</strong> to report a problem directly from the production floor. You can attach the data of the selected parts and pictures for context.</p><h2 id="editing-and-deleting" tabindex="-1">Editing and Deleting <a class="header-anchor" href="#editing-and-deleting" aria-label="Permalink to &quot;Editing and Deleting&quot;">​</a></h2><p>Hover a row to see its actions: <strong>Edit issue</strong> (title, text and category), <strong>Solve issue</strong> and <strong>Delete</strong>. The same buttons are in the issue detail.</p><h2 id="resolving-issues" tabindex="-1">Resolving Issues <a class="header-anchor" href="#resolving-issues" aria-label="Permalink to &quot;Resolving Issues&quot;">​</a></h2><p>To close an issue:</p><ol><li>Click <strong>Solve issue</strong> on its row or in the issue detail.</li><li>Select the design <strong>Revision</strong> in which the issue was solved.</li><li>Add a <strong>Comment</strong> explaining how it was fixed.</li><li>Click <strong>Submit</strong>.</li></ol><p>The issue is then marked as solved, and its detail shows the revision and the solving comment.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Click a column header to sort the table by title, constructible, category, user, creation date or status.</p>',24),n=[r];function l(d,u,h,g,c,p){return t(),s("div",null,n)}const b=e(a,[["render",l]]);export{f as __pageData,b as default};
